import{a as e,i as t,s as n,t as r}from"./app-CchzzT6L.js";var i=JSON.parse(`{"path":"/docker/docker-file.html","title":"Basic Syntax","lang":"en-US","frontmatter":{},"git":{"updatedTime":1740223686000,"contributors":[{"name":"Noei","username":"Noei","email":"logmanxsa@gmail.com","commits":1,"url":"https://github.com/Noei"},{"name":"hifat","username":"hifat","email":"logmanxsa@gmail.com","commits":1,"url":"https://github.com/hifat"}],"changelog":[{"hash":"160e4c7526d8c8ae36b6f71203e50947c1943ec9","time":1740223686000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add docker build content"},{"hash":"7dd2944069d3369db74006b406d5c7e97884c9de","time":1661707157000,"email":"logmanxsa@gmail.com","author":"Noei","message":"Edit docker content"}]},"filePathRelative":"docker/docker-file.md"}`),a={name:`docker-file.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="basic-syntax" tabindex="-1"><a class="header-anchor" href="#basic-syntax"><span>Basic Syntax</span></a></h1><h3 id="from" tabindex="-1"><a class="header-anchor" href="#from"><span>FROM</span></a></h3><p>Use base image that you want. If you don&#39;t use version tag default is :latest but not recommend because effect your app. Should use version tag</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">FROM</span><span style="color:#9ECBFF;"> python:3.9.6</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="workdir" tabindex="-1"><a class="header-anchor" href="#workdir"><span>WORKDIR</span></a></h3><p>Create directory in container image and open that directory</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">WORKDIR</span><span style="color:#9ECBFF;"> app</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="copy" tabindex="-1"><a class="header-anchor" href="#copy"><span>COPY</span></a></h3><p>Copy file from your dir to dir in container<br> COPY [your_dir] [container_dir]<br> Explain: Copy all file in your dir to /app in container. If your WORKDIR is /app/foo. It is will copy to /app/foo</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">COPY</span><span style="color:#9ECBFF;"> .</span><span style="color:#9ECBFF;"> .</span></span></span>
<span class="line"><span class="line"></span></span>
<span class="line"><span class="line"><span style="color:#6A737D;"># If you want copy to different dir</span></span></span>
<span class="line"><span class="line"><span style="color:#B392F0;">COPY</span><span style="color:#9ECBFF;"> .</span><span style="color:#9ECBFF;"> ./app/foo/bar</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="expose" tabindex="-1"><a class="header-anchor" href="#expose"><span>EXPOSE</span></a></h3><p>Container port</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">EXPOSE</span><span style="color:#79B8FF;"> 3000</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="entrypoint" tabindex="-1"><a class="header-anchor" href="#entrypoint"><span>ENTRYPOINT</span></a></h3><p>It is default executable. When container instance start, It run ENTRYPOINT<br> ** Some image build in default executable. It is not necessary to specify an ENTRYPOINT</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">ENTRYPOINT</span><span style="color:#E1E4E8;"> [</span><span style="color:#9ECBFF;">&quot;python&quot;</span><span style="color:#E1E4E8;">, </span><span style="color:#9ECBFF;">&quot;app.py&quot;]</span><span style="color:#6A737D;">     # python app.py</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="cmd" tabindex="-1"><a class="header-anchor" href="#cmd"><span>CMD</span></a></h3><p>If ENTRYPOINT is set, CMD become argument for ENTRYPOINT</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">CMD</span><span style="color:#E1E4E8;"> [</span><span style="color:#9ECBFF;">&quot;--host=0.0.0.0&quot;</span><span style="color:#E1E4E8;">]              </span><span style="color:#6A737D;"># python app.py --host=0.0.0.0</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="file" tabindex="-1"><a class="header-anchor" href="#file"><span>File</span></a></h2><h3 id="dockerignore" tabindex="-1"><a class="header-anchor" href="#dockerignore"><span>.dockerignore</span></a></h3><p>If your do not want some file when use COPY you can add file name in <code>.dockerignore</code></p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">node_modules</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div>`,23)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};